-- Dataset provenance: REAL / DEMO / TEST labels, import batches, validation runs.
--
-- `dataset` replaces the earlier `is_demo` boolean:
--   real — genuine, legitimately obtained game observations (attested at import)
--   demo — synthetic demonstration data generated by the app
--   test — synthetic or fixture data used to test the pipeline / protocol
-- The three are never mixed in any analysis.

-- ---------------------------------------------------------------------------
-- import_batches: one row per import, with provenance and checksums
-- ---------------------------------------------------------------------------
create table if not exists public.import_batches (
  id                    uuid primary key default gen_random_uuid(),
  dataset               text not null check (dataset in ('real', 'demo', 'test')),
  source_name           text not null check (char_length(source_name) between 1 and 64),
  collection_method     text not null check (collection_method in ('manual_record', 'official_export', 'authorized_api', 'synthetic', 'other')),
  provenance_notes      text not null check (char_length(provenance_notes) between 10 and 4000),
  attested              boolean not null default false,
  file_name             text check (char_length(file_name) <= 255),
  file_sha256           text check (file_sha256 ~ '^[0-9a-f]{64}$'),
  rows_sha256           text check (rows_sha256 ~ '^[0-9a-f]{64}$'),
  total_rows            integer not null default 0,
  valid_rows            integer not null default 0,
  rejected_rows         integer not null default 0,
  duplicates_in_file    integer not null default 0,
  already_stored        integer not null default 0,
  inserted_rows         integer not null default 0,
  first_round_time      timestamptz,
  last_round_time       timestamptz,
  collected_from        timestamptz,
  collected_to          timestamptz,
  quality_report        jsonb not null default '{}'::jsonb,
  imported_at           timestamptz not null default now(),
  -- Real data must be explicitly attested as genuine, legitimately obtained observations.
  constraint import_batches_real_attested check (dataset <> 'real' or (attested and collection_method <> 'synthetic')),
  constraint import_batches_synthetic_not_real check (collection_method <> 'synthetic' or dataset <> 'real')
);
create index if not exists import_batches_dataset_idx on public.import_batches (dataset, imported_at desc);

-- ---------------------------------------------------------------------------
-- aviator_rounds: is_demo -> dataset, plus batch link
-- ---------------------------------------------------------------------------
alter table public.aviator_rounds add column if not exists dataset text;
update public.aviator_rounds set dataset = case when is_demo then 'demo' else 'real' end where dataset is null;
alter table public.aviator_rounds alter column dataset set not null;
alter table public.aviator_rounds alter column dataset set default 'real';
alter table public.aviator_rounds drop constraint if exists aviator_rounds_dataset_check;
alter table public.aviator_rounds add constraint aviator_rounds_dataset_check check (dataset in ('real', 'demo', 'test'));
alter table public.aviator_rounds add column if not exists import_batch_id uuid references public.import_batches (id) on delete set null;

alter table public.aviator_rounds drop constraint if exists aviator_rounds_unique_round;
alter table public.aviator_rounds add constraint aviator_rounds_unique_round unique (dataset, round_time);
drop index if exists aviator_rounds_dataset_time_idx;
drop index if exists aviator_rounds_multiplier_idx;
create index if not exists aviator_rounds_dataset_time_idx on public.aviator_rounds (dataset, round_time desc);
create index if not exists aviator_rounds_dataset_multiplier_idx on public.aviator_rounds (dataset, multiplier);
create index if not exists aviator_rounds_batch_idx on public.aviator_rounds (import_batch_id);
alter table public.aviator_rounds drop column if exists is_demo;

-- ---------------------------------------------------------------------------
-- model_runs / predictions: is_demo -> dataset
-- ---------------------------------------------------------------------------
alter table public.model_runs add column if not exists dataset text;
update public.model_runs set dataset = case when is_demo then 'demo' else 'real' end where dataset is null;
alter table public.model_runs alter column dataset set not null;
alter table public.model_runs drop constraint if exists model_runs_dataset_check;
alter table public.model_runs add constraint model_runs_dataset_check check (dataset in ('real', 'demo', 'test'));
drop index if exists model_runs_dataset_created_idx;
create index if not exists model_runs_dataset_created_idx on public.model_runs (dataset, created_at desc);
alter table public.model_runs drop column if exists is_demo;

alter table public.predictions add column if not exists dataset text;
update public.predictions set dataset = case when is_demo then 'demo' else 'real' end where dataset is null;
alter table public.predictions alter column dataset set not null;
alter table public.predictions drop constraint if exists predictions_dataset_check;
alter table public.predictions add constraint predictions_dataset_check check (dataset in ('real', 'demo', 'test'));
drop index if exists predictions_dataset_kind_time_idx;
drop index if exists predictions_pending_idx;
create index if not exists predictions_dataset_kind_time_idx on public.predictions (dataset, kind, prediction_time desc);
create index if not exists predictions_pending_idx on public.predictions (dataset, kind) where result = 'pending';
alter table public.predictions drop column if exists is_demo;

-- ---------------------------------------------------------------------------
-- data_sources: allow a 'test' source type
-- ---------------------------------------------------------------------------
alter table public.data_sources drop constraint if exists data_sources_source_type_check;
alter table public.data_sources add constraint data_sources_source_type_check
  check (source_type in ('manual', 'csv', 'api', 'live_feed', 'demo', 'test'));
insert into public.data_sources (source_name, source_type, enabled, notes) values
  ('test', 'test', true, 'TEST DATA — synthetic or fixture data used to test the pipeline. Never real observations.')
on conflict (source_name) do nothing;

-- ---------------------------------------------------------------------------
-- validation_runs: pre-registered, frozen real-data validation protocol.
-- Each (protocol, stage, window) can be evaluated exactly once.
-- ---------------------------------------------------------------------------
create table if not exists public.validation_runs (
  id                  uuid primary key default gen_random_uuid(),
  dataset             text not null check (dataset in ('real', 'demo', 'test')),
  stage               text not null check (stage in ('final_test', 'confirmation')),
  status              text not null check (status in ('registered', 'running', 'completed', 'failed')),
  protocol_version    text not null,
  protocol_sha256     text not null,
  data_sha256         text not null,
  window_fingerprint  text not null,
  window_start        timestamptz not null,
  window_end          timestamptz not null,
  window_rounds       integer not null check (window_rounds > 0),
  development_rounds  integer not null,
  parent_run_id       uuid references public.validation_runs (id),
  job_id              text,
  result              jsonb,
  classification      text check (classification in ('NO_RELIABLE_EDGE', 'WEAK_SIGNAL', 'PROMISING_SIGNAL', 'STRONGER_SIGNAL', 'INSUFFICIENT_DATA')),
  error               text,
  registered_at       timestamptz not null default now(),
  completed_at        timestamptz,
  constraint validation_runs_once unique (dataset, protocol_sha256, stage, window_fingerprint),
  constraint validation_runs_confirmation_has_parent check (stage <> 'confirmation' or parent_run_id is not null)
);
create index if not exists validation_runs_dataset_idx on public.validation_runs (dataset, registered_at desc);

alter table public.import_batches enable row level security;
alter table public.validation_runs enable row level security;
drop policy if exists "read validation runs" on public.validation_runs;
create policy "read validation runs" on public.validation_runs for select to anon, authenticated using (true);
-- import_batches contains provenance notes: no public read policy.
revoke insert, update, delete on public.import_batches, public.validation_runs from anon, authenticated;

-- Predictions produced by a validation-protocol run are linked to it.
alter table public.predictions add column if not exists validation_run_id uuid references public.validation_runs (id) on delete cascade;
create index if not exists predictions_validation_run_idx on public.predictions (validation_run_id);
